async function main(ctx) {
  const input = ctx.input || {};

  const args = {
    prompt: {
      text: input.prompt
    },
    source: {
      repository: input.repository
    }
  };

  // Add optional model
  if (input.model) {
    args.model = input.model;
  }

  // Add optional ref to source
  if (input.ref) {
    args.source.ref = input.ref;
  }

  // Build target object if any target fields are present
  if (input.branchName || input.autoCreatePr || input.skipReviewerRequest || input.openAsCursorGithubApp) {
    args.target = {};
    if (input.branchName) args.target.branchName = input.branchName;
    if (input.autoCreatePr !== undefined) args.target.autoCreatePr = input.autoCreatePr;
    if (input.skipReviewerRequest !== undefined) args.target.skipReviewerRequest = input.skipReviewerRequest;
    if (input.openAsCursorGithubApp !== undefined) args.target.openAsCursorGithubApp = input.openAsCursorGithubApp;
  }

  // Build webhook object if webhook fields are present
  if (input.webhookUrl) {
    args.webhook = {
      url: input.webhookUrl
    };
    if (input.webhookSecret) {
      args.webhook.secret = input.webhookSecret;
    }
  }

  return args;
}

async function main(ctx) {
  const response = ctx.input || {};
  return response.body || response;
}
